async function main() {
  const filePath = process.argv[2] || 'input/data.csv';

  let content: string;
  try {
    content = await fs.promises.readFile(filePath, 'utf-8');
  } catch (err) {
    console.error(`Error reading file: ${err}`);
    return;
  }

  const records = await parse(content, {
    columns: true,
