for (int i = 0; i < names.Count; i++) {
    var name = names[i];
    var age = ages[i];
    var email = emails[i];
    var score = scores[i];

    var obj = new JsonObject() {
        ["Name"] = name,
        ["Age"] = age,
        ["Email"] = email,
        ["Score"] = score,
    };
    results.Add(obj);
}

