	}

	// Iterate and print primes up to N
	var primes []int
	for i := 2; i <= n; i++ {
		if isPrime(i) {
			primes = append(primes, i)
		}
	}

	// If there are primes, print each one on a new line
	for _, p := range primes {
		fmt.Println(p)
	}
